parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "city": {
      "type": "string",
      "description": "City only, from location or else from current_role_locations"
    },
    "university_n": {
      "type": "integer",
      "description": "n of the most recent bachelor's, master's or PhD education"
    },
    "headline_degree": {
      "type": "string",
      "description": "Degree name the headline gives, without dots, for example BSc"
    },
    "major": {
      "type": "string",
      "description": "Subject from the degree text, only when that education has no field"
    },
    "descriptions": {
      "type": "array",
      "description": "One short sentence per role that has a description",
      "items": {
        "type": "object",
        "properties": {
          "n": {
            "type": "integer"
          },
          "description": {
            "type": "string"
          }
        },
        "required": ["n", "description"]
      }
    }
  },
  "required": ["descriptions"]
}

